# Generated by test-lab — blind adversarial evaluation
"""Regression coverage for typed final-message extraction."""

from pathlib import Path

from models import SessionSpec
from result_watcher import extract_final_message
from session_store import SessionStore


def test_extract_final_message_uses_configured_file(tmp_path):
    answer_file = tmp_path / "answer.txt"
    answer_file.write_text("real final answer\n", encoding="utf-8")
    spec = SessionSpec(
        task_id="final-message",
        prompt="prompt",
        cwd=str(tmp_path),
        output_dir=str(tmp_path / "sessions"),
        env={"SUBAGENT_RUNNER_FINAL_MESSAGE_FILE": str(answer_file)},
    )
    store = SessionStore(spec.output_dir)
    state = store.create_session(spec)

    result = extract_final_message(store, state, spec)

    assert result["status"] == "ok"
    assert result["source"] == "configured_file"
    assert result["message"] == "real final answer"


def test_extract_final_message_replaces_ui_hook_output_with_pre_hook_transcript(tmp_path):
    answer_file = tmp_path / "answer.txt"
    answer_file.write_text(
        "I can't run the UI CDP verification meaningfully because no <target-url> exists.",
        encoding="utf-8",
    )
    spec = SessionSpec(
        task_id="hook-output",
        prompt="prompt",
        cwd=str(tmp_path),
        output_dir=str(tmp_path / "sessions"),
        env={"SUBAGENT_RUNNER_FINAL_MESSAGE_FILE": str(answer_file)},
    )
    store = SessionStore(spec.output_dir)
    state = store.create_session(spec)
    transcript_path = Path(store.paths(state.session_id).transcript_file)
    transcript_path.write_text(
        "startup\ncodex\nREAL DEEP REVIEW JSON\nhook: Stop\nI can't run the UI CDP verification.",
        encoding="utf-8",
    )

    result = extract_final_message(store, state, spec)

    assert result["status"] == "degraded"
    assert result["source"] == "transcript_pre_hook"
    assert result["message"] == "REAL DEEP REVIEW JSON"
    assert result["warnings"] == ["configured final-message file looked like terminal hook output"]
